mapper.select:
SELECT 
FROM record
WHERE user_id = #{userId}
AND type = #{type}
AND category = #{category}
AND account_type = #{accountType}
AND record_date >= #{startDate}
AND record_date <= #{endDate}
ORDER BY record_date DESC, create_time DESC

mapper.update:
UPDATE record
type = #{type}, amount = #{amount}, category = #{category}, account_type = #{accountType}, record_date = #{recordDate}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT
    COALESCE(SUM(CASE WHEN type = 1 THEN amount ELSE 0 END), 0) AS totalIncome,
    COALESCE(SUM(CASE WHEN type = 0 THEN amount ELSE 0 END), 0) AS totalExpense
FROM record
WHERE user_id = #{userId}
AND EXTRACT(YEAR FROM record_date) = #{year}
AND EXTRACT(MONTH FROM record_date) = #{month}

SELECT
    COALESCE(SUM(CASE WHEN type = 1 THEN amount ELSE 0 END), 0) AS totalIncome,
    COALESCE(SUM(CASE WHEN type = 0 THEN amount ELSE 0 END), 0) AS totalExpense
FROM record
WHERE user_id = #{userId}
AND EXTRACT(YEAR FROM record_date) = #{year}
AND EXTRACT(MONTH FROM record_date) = #{month}

SELECT
    category AS categoryName,
    SUM(amount) AS totalAmount
FROM record
WHERE user_id = #{userId}
AND type = #{type}
AND EXTRACT(YEAR FROM record_date) = #{year}
AND EXTRACT(MONTH FROM record_date) = #{month}
GROUP BY category
ORDER BY totalAmount DESC
